    how = intro(t('如何使用', 'HOW PAIA WORKS'), t('一句话，<br>不只用一次。', 'One thought.<br>More than one moment.'), t('照常与 AI 对话。让已经说过的话，有自己的位置，也有继续生长的方式。', 'Keep talking with AI. Give the words you have already shared a place to stay, and a way to grow.'), a('demo.html', t('直接体验产品示例', 'Try the interactive example'), 'text-link'))
    how += f'''<div class="nr-process-top wrap"><nav class="nr-process-index" aria-label="{t('使用步骤', 'The five steps')}">{''.join(f'<a href="#{slug}"><span>0{i + 1}</span><strong>{label}</strong><span aria-hidden="true">↗</span></a>' for i, (slug, label) in enumerate(steps))}</nav><p class="nr-scope">{t('以下展示正式计划的完整体验。当前为 Chrome / ChatGPT 邀请制内测。', 'The complete experience in the approved plan. Currently an invite-only Chrome / ChatGPT beta.')} {a('status.html', t('查看可用范围', 'View availability'))}</p></div>'''

    capture = f'''<figure class="nr-scene nr-scene-capture" data-reveal><div class="nr-window nr-capture-window">{window_bar('ChatGPT', t('示例会话', 'Example conversation'))}<div class="nr-conversation"><span class="nr-ui-label">{t('产品的第一步', 'A product’s first step')}</span><p class="nr-chat-message">{t('第一版先帮创作者找回自己的素材。生成更多内容，可以以后再说。', 'Start by helping creators find their own material. Generating more content can wait.')}</p><div class="nr-chat-response" aria-hidden="true"><span></span><span></span><span></span></div></div></div><div class="nr-capture-slip"><span class="nr-slip-icon">{icon('collect', 'mini-icon')}</span><div><strong>{t('留在 Input Archive', 'Kept in Input Archive')}</strong><span>{t('你的原话 · 来源 · 时间', 'Your words · Source · Time')}</span></div><span aria-hidden="true">↗</span></div>{sample_caption(t('界面示意 · 只保存已开启采集的受支持输入', 'Interface illustration · Capture applies only when enabled and supported'))}</figure>'''
    archive = f'''<figure class="nr-scene nr-scene-archive" data-reveal><div class="nr-window nr-reader-window">{window_bar('Input Archive', t('示例', 'Example'))}<div class="nr-reader"><div class="nr-reader-source"><span>ChatGPT</span><span>{t('产品探索 / 第一版', 'Product exploration / First release')}</span></div><h3>{t('先让自己的素材，<br>重新被找到。', 'Make your own material<br>findable again.')}</h3><p>{t('第一版先帮创作者找回自己的素材。', 'Start by helping creators find their own material.')}</p><p><mark>{t('生成更多内容，可以以后再说。', 'Generating more content can wait.')}</mark></p><details class="nr-source-detail"><summary>{t('核对这条输入的原话', 'Check the original input')} <span aria-hidden="true">+</span></summary><p>{t('“第一版先帮创作者找回自己的素材。生成更多内容，可以以后再说。”', '“Start by helping creators find their own material. Generating more content can wait.”')}</p><span>{t('虚构来源 · 示例会话', 'Fictional source · Example conversation')}</span></details></div></div>{sample_caption(t('找回一条输入，接上完整语境', 'Return to one input, with its context intact'))}</figure>'''
