    chosen_prompt = t('给出最强的反例和遗漏变量。', 'Give the strongest counterexample and missing variables.')
    prompt = f'''<figure class="nr-scene nr-scene-prompt" data-reveal><div class="nr-prompt-sheet"><div class="nr-prompt-sheet-header"><span class="nr-ui-label">{t('下一次对话', 'YOUR NEXT CONVERSATION')}</span><span aria-hidden="true">↗</span></div><p>{t('请评估这个产品方向。', 'Please evaluate this product direction.')}</p><div class="nr-prompt-insertion">{chosen_prompt}</div><span class="nr-ui-label">{t('填入后，仍由你检查并发送', 'Review it. Send it yourself.')}</span></div><div class="nr-prompt-palette" role="group" aria-label="{t('个人提示词示意', 'Personal prompt illustration')}"><div class="nr-prompt-choice nr-prompt-chosen"><span>{chosen_prompt}</span><span aria-hidden="true">↗</span></div><div class="nr-prompt-choice"><span>{t('先说明判断依据，再给出结论。', 'Explain the reasoning before giving your conclusion.')}</span></div><div class="nr-prompt-choice"><span>{t('请把下一步拆成可以执行的具体动作。', 'Break the next step into concrete actions I can take.')}</span></div></div>{sample_caption(t('个人提示词示意 · 不会自动发送', 'Personal prompt illustration · Never sends automatically'))}</figure>'''
