    how += '<div class="nr-process wrap">' + ''.join(f'''<section id="{slug}" class="nr-process-step nr-step-{slug}"><div class="nr-step-copy" data-reveal><span class="nr-step-number">{num}</span><h2>{title}</h2><p>{copy}</p><p class="nr-step-note">{note}</p></div>{visual}</section>''' for slug, num, title, copy, note, visual in flow) + '</div>' + invitation()
