    use = intro(t('使用场景', 'WAYS TO USE PAIA'), t('这一次，<br>从已有的积累开始。', 'This time,<br>start with what you know.'), t('一个项目，一个问题，一次选择。真正重要的事情，往往需要不止一次对话。', 'A project, a question, a decision. The things that matter rarely fit into a single conversation.'), f'<p class="nr-scope">{t("以下情景均为虚构示例。", "The following scenarios are fictional illustrations.")}</p>', 'nr-use-intro')
    cases = [
        ('project', '01', t('一个长期项目', 'AN ONGOING PROJECT'), t('边界记得住，<br>下一版才走得远。', 'Keep the boundaries.<br>Move the work forward.'), t('不必重新解释目标，也不必再次讨论已经放弃的方向。找到当时的决定，在新的任务里继续。', 'Keep the goal in view without explaining discarded options again. Recover the earlier decision and build on it.'), t('之前已经想清楚的', 'WHAT YOU ALREADY WORKED OUT'), t('第一版只验证素材找回。<br>面向独立创作者。<br>暂不做多人协作。', 'Validate retrieval in the first release.<br>For independent creators.<br>No collaboration features yet.'), t('下一次可以这样问', 'YOUR NEXT QUESTION'), t('在这些边界内，下一版最值得验证什么？', 'Within these boundaries, what should the next release test?'), t('Input Archive 找回决定；Thought Library 把项目放在一起。', 'Recover the decision in Input Archive. Keep the project together in Thought Library.')),
        ('research', '02', t('一个研究问题', 'A RESEARCH QUESTION'), t('接上推理，<br>保留每一步的条件。', 'Continue the reasoning.<br>Keep its conditions.'), t('找回先前的问题、假设和未解之处。引用是引用，试探是试探，自己的判断仍能回到来源核对。', 'Recover earlier questions, assumptions and open problems. Keep quotations and experiments distinct from your conclusions, with sources close at hand.'), t('先前留下的问题', 'THE QUESTION YOU KEPT'), t('这个结论依赖哪些假设？<br>哪一步仍然没有被验证？', 'Which assumptions does this conclusion depend on?<br>Which step is still untested?'), t('下一次可以这样问', 'YOUR NEXT QUESTION'), t('如果改变第二个假设，推理会从哪里开始不同？', 'If the second assumption changes, where does the reasoning begin to differ?'), t('沿主题连续阅读；需要时，回到那条原始输入。', 'Read continuously within a topic. Return to the original input when needed.')),
        ('decision', '03', t('一次重要选择', 'AN IMPORTANT DECISION'), t('新的信息，<br>值得一次新的判断。', 'New information.<br>A fresh point of view.'), t('过去的表达带着当时的背景。对照以前的限制与现在的变化，让选择跟上自己。', 'Your earlier words carry the circumstances of that moment. Compare the old constraints with what has changed, so your decision can change too.'), t('曾经的考虑', 'WHAT MATTERED THEN'), t('城市是首要条件。<br>也希望工作留下学习空间。', 'Location comes first.<br>The work should leave room to learn.'), t('现在重新比较', 'LOOK AT IT AGAIN'), t('工作内容更重要了。用更新后的条件，再比较这两个选择。', 'The work itself matters more now. Compare these two options using the updated priorities.'), t('修改自己的工作内容；AI Context 中的近况也可独立更新。', 'Revise your working content. Update current context independently in AI Context.')),
    ]
    use += '<div class="nr-case-list wrap">'
